import numpy as np
from scipy import ndimage

def shapes_of(a):
    out=[]
    for c in sorted(set(a.flatten())-{0}):
        lab,n=ndimage.label(a==c)
        for i in range(1,n+1):
            ys,xs=np.where(lab==i)
            r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
            sub=(a[r0:r1+1,c0:c1+1]==c)
            # hole: background cell in bbox not connected to bbox border
            bg=~sub
            labb,_=ndimage.label(bg)
            edge=set(labb[0,:])|set(labb[-1,:])|set(labb[:,0])|set(labb[:,-1])
            hole=any(l not in edge for l in set(labb.flatten())-{0})
            out.append(dict(color=c,r0=r0,c0=c0,sub=sub,box=hole))
    return out

def transform(g):
    a=np.array(g); H,W=a.shape
    out=np.zeros_like(a)
    sh=shapes_of(a)
    up=sorted([s for s in sh if s['box']],key=lambda s:s['r0'])
    dn=sorted([s for s in sh if not s['box']],key=lambda s:-s['r0'])
    def place(s,top):
        h,w=s['sub'].shape
        for t in range(max(top,0), H-h+1):
            reg=out[t:t+h,s['c0']:s['c0']+w]
            if not ((reg!=0)&s['sub']).any():
                out[t:t+h,s['c0']:s['c0']+w][s['sub']]=s['color']; return True
        return False
    for s in up: place(s,0)
